// ============================================================
// FreeLang Executor: Phase 9 Test Execution Layer
// ============================================================
// 프리랭 stdlib 테스트를 실행할 수 있는 확장 인터프리터
//
// 목표:
// - struct 리터럴 파싱 및 인스턴싱
// - 필드 접근 (x.field)
// - 함수 호출 (fn_name(args))
// - for range 루프
// - if/else 조건문
// - 내장 함수 (length, range, str, println)
//
// 라인: 300줄
// 테스트: 20개

use std::collections::HashMap;
use std::any::Any;

// ============================================================
// Value Type (확장)
// ============================================================

#[derive(Clone, Debug)]
pub enum Value {
    Integer(i64),
    Boolean(bool),
    String(String),
    Array(Vec<Value>),
    Struct(HashMap<String, Value>),
    Function(String, Vec<String>), // function_name, params
    Null,
}

impl Value {
    pub fn to_string(&self) -> String {
        match self {
            Value::Integer(n) => n.to_string(),
            Value::Boolean(b) => b.to_string(),
            Value::String(s) => s.clone(),
            Value::Array(_) => "[Array]".to_string(),
            Value::Struct(_) => "{Struct}".to_string(),
            Value::Function(name, _) => format!("fn {}", name),
            Value::Null => "null".to_string(),
        }
    }

    pub fn is_truthy(&self) -> bool {
        match self {
            Value::Boolean(b) => *b,
            Value::Null => false,
            Value::Integer(0) => false,
            _ => true,
        }
    }
}

// ============================================================
// Runtime Environment
// ============================================================

pub struct Environment {
    variables: HashMap<String, Value>,
    functions: HashMap<String, String>, // function_name -> body
}

impl Environment {
    pub fn new() -> Self {
        Environment {
            variables: HashMap::new(),
            functions: HashMap::new(),
        }
    }

    pub fn get(&self, name: &str) -> Option<Value> {
        self.variables.get(name).cloned()
    }

    pub fn set(&mut self, name: String, value: Value) {
        self.variables.insert(name, value);
    }

    pub fn get_function(&self, name: &str) -> Option<String> {
        self.functions.get(name).cloned()
    }

    pub fn define_function(&mut self, name: String, body: String) {
        self.functions.insert(name, body);
    }
}

// ============================================================
// Expression Types
// ============================================================

#[derive(Clone, Debug)]
pub enum Expr {
    // Literals
    Literal(Value),

    // Variables
    Variable(String),

    // Binary Operations
    BinOp {
        left: Box<Expr>,
        op: String,
        right: Box<Expr>,
    },

    // Field Access: x.field
    FieldAccess {
        object: Box<Expr>,
        field: String,
    },

    // Function Call: fn_name(arg1, arg2)
    FunctionCall {
        name: String,
        args: Vec<Expr>,
    },

    // Array Append: arr + [item]
    ArrayAppend {
        array: Box<Expr>,
        item: Box<Expr>,
    },

    // Struct Constructor
    StructConstruct {
        name: String,
        fields: HashMap<String, Expr>,
    },
}

// ============================================================
// Statement Types
// ============================================================

#[derive(Clone, Debug)]
pub enum Stmt {
    // Variable Declaration: var x = expr
    VarDecl {
        name: String,
        value: Expr,
    },

    // Variable Assignment: x = expr
    Assign {
        name: String,
        value: Expr,
    },

    // For Loop: for i in range(0, 10) { ... }
    ForLoop {
        var: String,
        start: i64,
        end: i64,
        body: Vec<Stmt>,
    },

    // If Statement: if cond { ... } else { ... }
    If {
        condition: Expr,
        then_body: Vec<Stmt>,
        else_body: Option<Vec<Stmt>>,
    },

    // Return Statement
    Return(Option<Expr>),

    // Expression Statement
    Expr(Expr),
}

// ============================================================
// Executor
// ============================================================

pub struct Executor {
    env: Environment,
    return_value: Option<Value>,
}

impl Executor {
    pub fn new() -> Self {
        Executor {
            env: Environment::new(),
            return_value: None,
        }
    }

    // Evaluate expression
    pub fn eval_expr(&self, expr: &Expr) -> Value {
        match expr {
            Expr::Literal(val) => val.clone(),

            Expr::Variable(name) => {
                self.env.get(name).unwrap_or(Value::Null)
            }

            Expr::BinOp { left, op, right } => {
                let lval = self.eval_expr(left);
                let rval = self.eval_expr(right);
                self.apply_binop(&lval, op, &rval)
            }

            Expr::FieldAccess { object, field } => {
                match self.eval_expr(object) {
                    Value::Struct(fields) => {
                        fields.get(field).cloned().unwrap_or(Value::Null)
                    }
                    _ => Value::Null,
                }
            }

            Expr::FunctionCall { name, args } => {
                self.call_builtin(name, args)
            }

            Expr::ArrayAppend { array, item } => {
                match self.eval_expr(array) {
                    Value::Array(mut arr) => {
                        arr.push(self.eval_expr(item));
                        Value::Array(arr)
                    }
                    _ => Value::Null,
                }
            }

            Expr::StructConstruct { name, fields } => {
                let mut struct_val = HashMap::new();
                for (k, v) in fields {
                    struct_val.insert(k.clone(), self.eval_expr(v));
                }
                Value::Struct(struct_val)
            }
        }
    }

    // Apply binary operators
    fn apply_binop(&self, left: &Value, op: &str, right: &Value) -> Value {
        match (left, right) {
            (Value::Integer(l), Value::Integer(r)) => {
                let result = match op {
                    "+" => l + r,
                    "-" => l - r,
                    "*" => l * r,
                    "/" => if *r != 0 { l / r } else { 0 },
                    "%" => if *r != 0 { l % r } else { 0 },
                    "==" => return Value::Boolean(l == r),
                    "!=" => return Value::Boolean(l != r),
                    "<" => return Value::Boolean(l < r),
                    ">" => return Value::Boolean(l > r),
                    "<=" => return Value::Boolean(l <= r),
                    ">=" => return Value::Boolean(l >= r),
                    _ => 0,
                };
                Value::Integer(result)
            }

            (Value::String(l), Value::String(r)) if op == "+" => {
                Value::String(format!("{}{}", l, r))
            }

            _ => Value::Null,
        }
    }

    // Built-in functions
    fn call_builtin(&self, name: &str, args: &[Expr]) -> Value {
        match name {
            "println" => {
                for arg in args {
                    println!("{}", self.eval_expr(arg).to_string());
                }
                Value::Null
            }

            "length" => {
                if let Some(arg) = args.first() {
                    match self.eval_expr(arg) {
                        Value::Array(arr) => Value::Integer(arr.len() as i64),
                        Value::String(s) => Value::Integer(s.len() as i64),
                        _ => Value::Integer(0),
                    }
                } else {
                    Value::Integer(0)
                }
            }

            "range" => {
                // Returns an array [start, start+1, ..., end-1]
                if args.len() >= 2 {
                    let start = match self.eval_expr(&args[0]) {
                        Value::Integer(n) => n,
                        _ => 0,
                    };
                    let end = match self.eval_expr(&args[1]) {
                        Value::Integer(n) => n,
                        _ => 0,
                    };

                    let mut result = Vec::new();
                    for i in start..end {
                        result.push(Value::Integer(i));
                    }
                    Value::Array(result)
                } else {
                    Value::Array(vec![])
                }
            }

            "str" => {
                if let Some(arg) = args.first() {
                    Value::String(self.eval_expr(arg).to_string())
                } else {
                    Value::String(String::new())
                }
            }

            _ => Value::Null,
        }
    }

    // Execute statement
    pub fn exec_stmt(&mut self, stmt: &Stmt) {
        match stmt {
            Stmt::VarDecl { name, value } => {
                let val = self.eval_expr(value);
                self.env.set(name.clone(), val);
            }

            Stmt::Assign { name, value } => {
                let val = self.eval_expr(value);
                self.env.set(name.clone(), val);
            }

            Stmt::ForLoop { var, start, end, body } => {
                for i in *start..*end {
                    self.env.set(var.clone(), Value::Integer(i));
                    for stmt in body {
                        self.exec_stmt(stmt);
                    }
                }
            }

            Stmt::If { condition, then_body, else_body } => {
                let cond_val = self.eval_expr(condition);
                if cond_val.is_truthy() {
                    for stmt in then_body {
                        self.exec_stmt(stmt);
                    }
                } else if let Some(els) = else_body {
                    for stmt in els {
                        self.exec_stmt(stmt);
                    }
                }
            }

            Stmt::Return(Some(expr)) => {
                self.return_value = Some(self.eval_expr(expr));
            }

            Stmt::Return(None) => {
                self.return_value = Some(Value::Null);
            }

            Stmt::Expr(expr) => {
                let _ = self.eval_expr(expr);
            }
        }
    }
}

// ============================================================
// Tests (20개)
// ============================================================

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_executor_creation() {
        let _executor = Executor::new();
        println!("✓ Executor: creation works");
    }

    #[test]
    fn test_integer_literal() {
        let executor = Executor::new();
        let expr = Expr::Literal(Value::Integer(42));
        assert_eq!(executor.eval_expr(&expr).to_string(), "42");
        println!("✓ Executor: integer literal works");
    }

    #[test]
    fn test_string_literal() {
        let executor = Executor::new();
        let expr = Expr::Literal(Value::String("hello".to_string()));
        assert_eq!(executor.eval_expr(&expr).to_string(), "hello");
        println!("✓ Executor: string literal works");
    }

    #[test]
    fn test_variable_storage() {
        let mut executor = Executor::new();
        executor.env.set("x".to_string(), Value::Integer(10));
        let expr = Expr::Variable("x".to_string());
        assert_eq!(executor.eval_expr(&expr).to_string(), "10");
        println!("✓ Executor: variable storage works");
    }

    #[test]
    fn test_binary_op_addition() {
        let executor = Executor::new();
        let expr = Expr::BinOp {
            left: Box::new(Expr::Literal(Value::Integer(5))),
            op: "+".to_string(),
            right: Box::new(Expr::Literal(Value::Integer(3))),
        };
        assert_eq!(executor.eval_expr(&expr).to_string(), "8");
        println!("✓ Executor: binary op addition works");
    }

    #[test]
    fn test_struct_construction() {
        let mut executor = Executor::new();
        let mut fields = HashMap::new();
        fields.insert("name".to_string(), Expr::Literal(Value::String("test".to_string())));
        fields.insert("value".to_string(), Expr::Literal(Value::Integer(42)));

        let expr = Expr::StructConstruct {
            name: "TestStruct".to_string(),
            fields,
        };
        let result = executor.eval_expr(&expr);
        matches!(result, Value::Struct(_));
        println!("✓ Executor: struct construction works");
    }

    #[test]
    fn test_field_access() {
        let executor = Executor::new();
        let mut fields = HashMap::new();
        fields.insert("x".to_string(), Value::Integer(10));

        let expr = Expr::FieldAccess {
            object: Box::new(Expr::Literal(Value::Struct(fields))),
            field: "x".to_string(),
        };
        assert_eq!(executor.eval_expr(&expr).to_string(), "10");
        println!("✓ Executor: field access works");
    }

    #[test]
    fn test_array_append() {
        let executor = Executor::new();
        let arr = Value::Array(vec![Value::Integer(1), Value::Integer(2)]);
        let expr = Expr::ArrayAppend {
            array: Box::new(Expr::Literal(arr)),
            item: Box::new(Expr::Literal(Value::Integer(3))),
        };
        let result = executor.eval_expr(&expr);
        if let Value::Array(arr) = result {
            assert_eq!(arr.len(), 3);
        }
        println!("✓ Executor: array append works");
    }

    #[test]
    fn test_for_loop() {
        let mut executor = Executor::new();
        let body = vec![
            Stmt::Expr(Expr::Literal(Value::Null)),
        ];
        let stmt = Stmt::ForLoop {
            var: "i".to_string(),
            start: 0,
            end: 3,
            body,
        };
        executor.exec_stmt(&stmt);
        println!("✓ Executor: for loop works");
    }

    #[test]
    fn test_if_statement() {
        let mut executor = Executor::new();
        let then_body = vec![
            Stmt::VarDecl {
                name: "x".to_string(),
                value: Expr::Literal(Value::Integer(10)),
            },
        ];
        let stmt = Stmt::If {
            condition: Expr::Literal(Value::Boolean(true)),
            then_body,
            else_body: None,
        };
        executor.exec_stmt(&stmt);
        assert_eq!(executor.env.get("x").unwrap().to_string(), "10");
        println!("✓ Executor: if statement works");
    }

    #[test]
    fn test_length_builtin() {
        let executor = Executor::new();
        let expr = Expr::FunctionCall {
            name: "length".to_string(),
            args: vec![
                Expr::Literal(Value::Array(vec![Value::Integer(1), Value::Integer(2)]))
            ],
        };
        assert_eq!(executor.eval_expr(&expr).to_string(), "2");
        println!("✓ Executor: length builtin works");
    }

    #[test]
    fn test_range_builtin() {
        let executor = Executor::new();
        let expr = Expr::FunctionCall {
            name: "range".to_string(),
            args: vec![
                Expr::Literal(Value::Integer(0)),
                Expr::Literal(Value::Integer(3)),
