// ============================================================
// FreeLang Executor Integration Tests
// ============================================================
// Phase 9 Stage 4: Test Executor end-to-end functionality
// Tests the core execution engine with programmatic AST construction

use freelang_compiler::*;
use std::collections::HashMap;

// ============================================================
// Test 1: Integer Literal Evaluation
// ============================================================

#[test]
fn test_integer_literal_evaluation() {
    let executor = Executor::new();
    let expr = Expr::Literal(Value::Integer(42));
    let result = executor.eval_expr(&expr);

    assert_eq!(result.to_string(), "42");
    println!("✓ Test 1: Integer literal evaluation");
}

// ============================================================
// Test 2: String Literal Evaluation
// ============================================================

#[test]
fn test_string_literal_evaluation() {
    let executor = Executor::new();
    let expr = Expr::Literal(Value::String("hello".to_string()));
    let result = executor.eval_expr(&expr);

    assert_eq!(result.to_string(), "hello");
    println!("✓ Test 2: String literal evaluation");
}

// ============================================================
// Test 3: Variable Declaration and Assignment
// ============================================================

#[test]
fn test_variable_declaration_and_assignment() {
    let mut executor = Executor::new();

    let stmt = Stmt::VarDecl {
        name: "x".to_string(),
        value: Expr::Literal(Value::Integer(10)),
    };

    executor.exec_stmt(&stmt);
    let result = executor.env.get("x").unwrap_or(Value::Null);

    assert_eq!(result.to_string(), "10");
    println!("✓ Test 3: Variable declaration and assignment");
}

// ============================================================
// Test 4: Struct Construction and Field Access
// ============================================================

#[test]
fn test_struct_construction_and_field_access() {
    let mut executor = Executor::new();

    let mut fields = HashMap::new();
    fields.insert("name".to_string(), Expr::Literal(Value::String("Point".to_string())));
    fields.insert("x".to_string(), Expr::Literal(Value::Integer(10)));
    fields.insert("y".to_string(), Expr::Literal(Value::Integer(20)));

    let struct_expr = Expr::StructConstruct {
        name: "Point".to_string(),
        fields,
    };

    let result = executor.eval_expr(&struct_expr);
    executor.env.set("p".to_string(), result);

    let access = Expr::FieldAccess {
        object: Box::new(Expr::Variable("p".to_string())),
        field: "x".to_string(),
    };

    let field_val = executor.eval_expr(&access);
    assert_eq!(field_val.to_string(), "10");
    println!("✓ Test 4: Struct construction and field access");
}

// ============================================================
// Test 5: For-Range Loop Execution
// ============================================================

#[test]
fn test_for_range_loop_execution() {
    let mut executor = Executor::new();

    let body = vec![
        Stmt::Expr(Expr::Literal(Value::Null)),
    ];

    let stmt = Stmt::ForLoop {
        var: "i".to_string(),
        start: 0,
        end: 5,
        body,
    };

    executor.exec_stmt(&stmt);

    let final_val = executor.env.get("i").unwrap_or(Value::Null);
    assert_eq!(final_val.to_string(), "4");
    println!("✓ Test 5: For-range loop execution");
}

// ============================================================
// Test 6: If/Else Branching
// ============================================================

#[test]
fn test_if_else_branching() {
    let mut executor = Executor::new();

    let then_body = vec![
        Stmt::VarDecl {
            name: "result".to_string(),
            value: Expr::Literal(Value::String("yes".to_string())),
        },
    ];

    let else_body = vec![
        Stmt::VarDecl {
            name: "result".to_string(),
            value: Expr::Literal(Value::String("no".to_string())),
        },
    ];

    let stmt = Stmt::If {
        condition: Expr::Literal(Value::Boolean(true)),
        then_body,
        else_body: Some(else_body),
    };

    executor.exec_stmt(&stmt);
    let result = executor.env.get("result").unwrap_or(Value::Null);
    assert_eq!(result.to_string(), "yes");
    println!("✓ Test 6: If/else branching");
}

// ============================================================
// Test 7: Array Append and Length
// ============================================================

#[test]
fn test_array_append_and_length() {
    let executor = Executor::new();

    let arr = Value::Array(vec![Value::Integer(1), Value::Integer(2)]);
    let expr = Expr::ArrayAppend {
        array: Box::new(Expr::Literal(arr)),
        item: Box::new(Expr::Literal(Value::Integer(3))),
    };

    let result = executor.eval_expr(&expr);

    if let Value::Array(arr) = result {
        assert_eq!(arr.len(), 3);
    } else {
        panic!("Expected array");
    }

    println!("✓ Test 7: Array append and length");
}

// ============================================================
// Test 8: Binary Operations (Arithmetic + Comparison)
// ============================================================

#[test]
fn test_binary_operations_arithmetic_and_comparison() {
    let executor = Executor::new();

    // Arithmetic: 2 + 3 * 4 = 2 + 12 = 14
    let add_expr = Expr::BinOp {
        left: Box::new(Expr::Literal(Value::Integer(2))),
        op: "+".to_string(),
        right: Box::new(Expr::Literal(Value::Integer(3))),
    };

    let result = executor.eval_expr(&add_expr);
    assert_eq!(result.to_string(), "5");

    // Comparison: 5 < 10 = true
    let cmp_expr = Expr::BinOp {
        left: Box::new(Expr::Literal(Value::Integer(5))),
        op: "<".to_string(),
        right: Box::new(Expr::Literal(Value::Integer(10))),
    };

    let result = executor.eval_expr(&cmp_expr);
    assert!(matches!(result, Value::Boolean(true)));
    println!("✓ Test 8: Binary operations (arithmetic + comparison)");
}

// ============================================================
// Test 9: Nested Expression Evaluation
// ============================================================

#[test]
fn test_nested_expression_evaluation() {
    let executor = Executor::new();

    // (2 + 3) * 4 = 5 * 4 = 20
    let expr = Expr::BinOp {
        left: Box::new(Expr::BinOp {
            left: Box::new(Expr::Literal(Value::Integer(2))),
            op: "+".to_string(),
            right: Box::new(Expr::Literal(Value::Integer(3))),
        }),
        op: "*".to_string(),
        right: Box::new(Expr::Literal(Value::Integer(4))),
    };

    let result = executor.eval_expr(&expr);
    assert_eq!(result.to_string(), "20");
    println!("✓ Test 9: Nested expression evaluation");
}

// ============================================================
// Test 10: Complex Struct Workflow
// ============================================================

#[test]
fn test_complex_struct_workflow() {
    let mut executor = Executor::new();

    // Create a struct with multiple fields
    let mut fields = HashMap::new();
