    95→
    96→#[derive(Clone, Debug)]
    97→pub enum Expr {
    98→    // Literals
    99→    Literal(Value),
   100→
   101→    // Variables
   102→    Variable(String),
   103→
   104→    // Binary Operations
   105→    BinOp {
   106→        left: Box<Expr>,
   107→        op: String,
   108→        right: Box<Expr>,
   109→    },
   110→
