   112→    FieldAccess {
   113→        object: Box<Expr>,
   114→        field: String,
   115→    },
   116→
   117→    // Function Call: fn_name(arg1, arg2)
   118→    FunctionCall {
   119→        name: String,
   120→        args: Vec<Expr>,
   121→    },
   122→
   123→    // Array Append: arr + [item]
   124→    ArrayAppend {
   125→        array: Box<Expr>,
   126→        item: Box<Expr>,
   127→    },
   128→
   129→    // Struct Constructor
   130→    StructConstruct {
   131→        name: String,
   132→        fields: HashMap<String, Expr>,
