   139→
   140→#[derive(Clone, Debug)]
   141→pub enum Stmt {
   142→    // Variable Declaration: var x = expr
   143→    VarDecl {
   144→        name: String,
   145→        value: Expr,
   146→    },
   147→
   148→    // Variable Assignment: x = expr
   149→    Assign {
   150→        name: String,
   151→        value: Expr,
   152→    },
   153→
   154→    // For Loop: for i in range(0, 10) { ... }
   155→    ForLoop {
   156→        var: String,
   157→        start: i64,
   158→        end: i64,
   159→        body: Vec<Stmt>,
   160→    },
   161→
   162→    // If Statement: if cond { ... } else { ... }
   163→    If {
   164→        condition: Expr,
   165→        then_body: Vec<Stmt>,
   166→        else_body: Option<Vec<Stmt>>,
