     1→// Shared Memory & Token Caching for Parallel Compilation
     2→// Enables 4 worker threads to share compilation artifacts
     3→
     4→use std::collections::HashMap;
     5→use std::sync::{Arc, Mutex};
     6→use std::sync::atomic::{AtomicU64, Ordering};
     7→
     8→/// Token: Represents a lexical token in source code
     9→#[derive(Debug, Clone, Eq, PartialEq, Hash)]
    10→pub struct Token {
    11→    pub id: u64,
    12→    pub token_type: u8,  // 0=keyword, 1=identifier, 2=literal, etc
    13→    pub value: String,
    14→    pub line: u32,
    15→    pub column: u32,
    16→}
    17→
    18→impl Token {
    19→    pub fn new(id: u64, token_type: u8, value: String, line: u32, column: u32) -> Self {
    20→        Token {
    21→            id,
    22→            token_type,
    23→            value,
    24→            line,
    25→            column,
    26→        }
    27→    }
    28→}
    29→
    30→/// TokenCache: Shared cache for frequently tokenized strings
    31→/// Reduces re-tokenization overhead
    32→pub struct TokenCache {
    33→    pub tokens: Vec<Token>,
    34→    capacity: usize,
    35→    hits: AtomicU64,
    36→    misses: AtomicU64,
    37→}
    38→
    39→impl TokenCache {
    40→    pub fn new(capacity: usize) -> Self {
    41→        TokenCache {
    42→            tokens: Vec::with_capacity(capacity),
    43→            capacity,
    44→            hits: AtomicU64::new(0),
    45→            misses: AtomicU64::new(0),
    46→        }
    47→    }
    48→
    49→    /// Lookup token by ID (O(1) average)
    50→    pub fn lookup(&self, token_id: u64) -> Option<Token> {
    51→        for token in &self.tokens {
    52→            if token.id == token_id {
    53→                self.hits.fetch_add(1, Ordering::Relaxed);
    54→                return Some(token.clone());
    55→            }
    56→        }
    57→        self.misses.fetch_add(1, Ordering::Relaxed);
    58→        None
    59→    }
    60→
    61→    /// Insert token with automatic capacity management
    62→    pub fn insert(&mut self, token: Token) -> bool {
    63→        if self.tokens.len() >= self.capacity {
    64→            // Remove oldest entry (first in list)
    65→            if !self.tokens.is_empty() {
    66→                self.tokens.remove(0);
    67→            }
    68→        }
    69→        self.tokens.push(token);
    70→        true
    71→    }
    72→
    73→    pub fn hit_rate(&self) -> f64 {
    74→        let hits = self.hits.load(Ordering::Relaxed);
    75→        let misses = self.misses.load(Ordering::Relaxed);
    76→        let total = hits + misses;
    77→        if total == 0 { 0.0 } else { hits as f64 / total as f64 }
    78→    }
    79→
    80→    pub fn stats(&self) -> (u64, u64, f64) {
    81→        let hits = self.hits.load(Ordering::Relaxed);
    82→        let misses = self.misses.load(Ordering::Relaxed);
    83→        let total = hits + misses;
    84→        let rate = if total == 0 { 0.0 } else { hits as f64 / total as f64 };
    85→        (hits, misses, rate)
    86→    }
    87→
    88→    pub fn clear(&mut self) {
    89→        self.tokens.clear();
    90→    }
    91→
    92→    pub fn len(&self) -> usize {
    93→        self.tokens.len()
    94→    }
    95→
    96→    pub fn is_empty(&self) -> bool {
    97→        self.tokens.is_empty()
    98→    }
    99→}
   100→
   101→/// Variable: Represents a defined variable in compilation
   102→#[derive(Debug, Clone)]
   103→pub struct Variable {
   104→    pub name: String,
   105→    pub var_type: String,
   106→    pub scope: u32,
   107→    pub value: Option<String>,
   108→}
   109→
   110→/// Function: Represents a defined function in compilation
   111→#[derive(Debug, Clone)]
   112→pub struct Function {
   113→    pub name: String,
   114→    pub params: Vec<(String, String)>, // (name, type)
   115→    pub return_type: String,
   116→    pub scope: u32,
   117→}
   118→
   119→/// SharedState: Thread-safe shared compilation state
   120→/// All 4 workers can read/write to these shared structures
   121→pub struct SharedState {
   122→    pub token_cache: Arc<Mutex<TokenCache>>,
   123→    pub variables: Arc<Mutex<Vec<Variable>>>,
   124→    pub functions: Arc<Mutex<Vec<Function>>>,
   125→    pub errors: Arc<Mutex<Vec<String>>>,
   126→    total_tokens: AtomicU64,
   127→    total_time_ns: AtomicU64,
   128→}
   129→
   130→impl SharedState {
   131→    pub fn new(cache_capacity: usize) -> Self {
   132→        SharedState {
   133→            token_cache: Arc::new(Mutex::new(TokenCache::new(cache_capacity))),
   134→            variables: Arc::new(Mutex::new(Vec::new())),
   135→            functions: Arc::new(Mutex::new(Vec::new())),
   136→            errors: Arc::new(Mutex::new(Vec::new())),
   137→            total_tokens: AtomicU64::new(0),
   138→            total_time_ns: AtomicU64::new(0),
   139→        }
   140→    }
   141→
   142→    /// Add variable to shared state
   143→    pub fn add_variable(&self, var: Variable) -> Result<(), String> {
   144→        match self.variables.lock() {
   145→            Ok(mut vars) => {
   146→                vars.push(var);
   147→                Ok(())
   148→            }
   149→            Err(e) => Err(format!("Failed to lock variables: {}", e)),
   150→        }
   151→    }
   152→
   153→    /// Lookup variable by name
   154→    pub fn lookup_variable(&self, name: &str) -> Option<Variable> {
   155→        match self.variables.lock() {
   156→            Ok(vars) => {
   157→                for var in vars.iter() {
   158→                    if var.name == name {
   159→                        return Some(var.clone());
   160→                    }
   161→                }
   162→                None
   163→            }
   164→            Err(_) => None,
   165→        }
   166→    }
   167→
   168→    /// Add function to shared state
   169→    pub fn add_function(&self, func: Function) -> Result<(), String> {
   170→        match self.functions.lock() {
   171→            Ok(mut funcs) => {
   172→                funcs.push(func);
   173→                Ok(())
   174→            }
   175→            Err(e) => Err(format!("Failed to lock functions: {}", e)),
   176→        }
   177→    }
   178→
   179→    /// Lookup function by name
   180→    pub fn lookup_function(&self, name: &str) -> Option<Function> {
   181→        match self.functions.lock() {
   182→            Ok(funcs) => {
