// Shared Memory & Token Caching for Parallel Compilation
// Enables 4 worker threads to share compilation artifacts

use std::collections::{HashMap, VecDeque};
use std::sync::{Arc, Mutex};
use std::sync::atomic::{AtomicU64, Ordering};

/// Token: Represents a lexical token in source code
#[derive(Debug, Clone, Eq, PartialEq, Hash)]
pub struct Token {
    pub id: u64,
    pub token_type: u8,  // 0=keyword, 1=identifier, 2=literal, etc
    pub value: String,
    pub line: u32,
    pub column: u32,
}

impl Token {
    pub fn new(id: u64, token_type: u8, value: String, line: u32, column: u32) -> Self {
        Token {
            id,
            token_type,
            value,
            line,
            column,
        }
    }
}

/// TokenCache: Shared cache for frequently tokenized strings
/// Reduces re-tokenization overhead (O(1) lookup via HashMap)
pub struct TokenCache {
    tokens: HashMap<u64, Token>,
    insertion_order: VecDeque<u64>,  // Track insertion order for LRU eviction
    capacity: usize,
    hits: u64,      // Now plain u64 (Mutex already provides exclusive access)
    misses: u64,
}

impl TokenCache {
    pub fn new(capacity: usize) -> Self {
        TokenCache {
            tokens: HashMap::with_capacity(capacity),
            insertion_order: VecDeque::with_capacity(capacity),
            capacity,
            hits: 0,
            misses: 0,
        }
    }

    /// Lookup token by ID (O(1) - HashMap lookup)
    pub fn lookup(&mut self, token_id: u64) -> Option<Token> {
        match self.tokens.get(&token_id) {
            Some(token) => {
                self.hits += 1;
                Some(token.clone())
            }
            None => {
                self.misses += 1;
                None
            }
        }
    }

    /// Insert token with automatic LRU capacity management (O(1) amortized)
    pub fn insert(&mut self, token: Token) -> bool {
        let token_id = token.id;

        // If at capacity and token not already cached, evict oldest
        if self.tokens.len() >= self.capacity && !self.tokens.contains_key(&token_id) {
            if let Some(oldest_id) = self.insertion_order.pop_front() {
                self.tokens.remove(&oldest_id);
            }
        }

        // Insert token
        self.tokens.insert(token_id, token);

        // Track insertion order (only if new token)
        if self.insertion_order.len() < self.capacity {
            self.insertion_order.push_back(token_id);
        }

        true
    }

    pub fn hit_rate(&self) -> f64 {
        let total = self.hits + self.misses;
        if total == 0 { 0.0 } else { self.hits as f64 / total as f64 }
    }

    pub fn stats(&self) -> (u64, u64, f64) {
        let total = self.hits + self.misses;
        let rate = if total == 0 { 0.0 } else { self.hits as f64 / total as f64 };
        (self.hits, self.misses, rate)
    }

    pub fn clear(&mut self) {
        self.tokens.clear();
        self.insertion_order.clear();
    }

    pub fn len(&self) -> usize {
        self.tokens.len()
    }

    pub fn is_empty(&self) -> bool {
        self.tokens.is_empty()
    }
}

