// Shared Memory & Token Caching for Parallel Compilation
// Enables 4 worker threads to share compilation artifacts

use std::collections::{HashMap, VecDeque};
use std::sync::{Arc, Mutex};
use std::sync::atomic::{AtomicU64, Ordering};

/// Token: Represents a lexical token in source code
#[derive(Debug, Clone, Eq, PartialEq, Hash)]
pub struct Token {
    pub id: u64,
    pub token_type: u8,  // 0=keyword, 1=identifier, 2=literal, etc
    pub value: String,
    pub line: u32,
    pub column: u32,
}

impl Token {
    pub fn new(id: u64, token_type: u8, value: String, line: u32, column: u32) -> Self {
        Token {
            id,
            token_type,
            value,
            line,
            column,
        }
    }
}

/// TokenCache: Shared cache for frequently tokenized strings
/// Reduces re-tokenization overhead (O(1) lookup via HashMap)
pub struct TokenCache {
    tokens: HashMap<u64, Token>,
    insertion_order: VecDeque<u64>,  // Track insertion order for LRU eviction
    capacity: usize,
    hits: u64,      // Now plain u64 (Mutex already provides exclusive access)
    misses: u64,
}

impl TokenCache {
    pub fn new(capacity: usize) -> Self {
        TokenCache {
            tokens: HashMap::with_capacity(capacity),
            insertion_order: VecDeque::with_capacity(capacity),
            capacity,
            hits: 0,
            misses: 0,
        }
    }

    /// Lookup token by ID (O(1) - HashMap lookup)
    pub fn lookup(&mut self, token_id: u64) -> Option<Token> {
        match self.tokens.get(&token_id) {
            Some(token) => {
                self.hits += 1;
                Some(token.clone())
            }
            None => {
                self.misses += 1;
                None
            }
        }
    }

    /// Insert token with automatic LRU capacity management (O(1) amortized)
    pub fn insert(&mut self, token: Token) -> bool {
        let token_id = token.id;

        // If at capacity and token not already cached, evict oldest
        if self.tokens.len() >= self.capacity && !self.tokens.contains_key(&token_id) {
            if let Some(oldest_id) = self.insertion_order.pop_front() {
                self.tokens.remove(&oldest_id);
            }
        }

        // Insert token
        self.tokens.insert(token_id, token);

        // Track insertion order (only if new token)
        if self.insertion_order.len() < self.capacity {
            self.insertion_order.push_back(token_id);
        }

        true
    }

    pub fn hit_rate(&self) -> f64 {
        let total = self.hits + self.misses;
        if total == 0 { 0.0 } else { self.hits as f64 / total as f64 }
    }

    pub fn stats(&self) -> (u64, u64, f64) {
        let total = self.hits + self.misses;
        let rate = if total == 0 { 0.0 } else { self.hits as f64 / total as f64 };
        (self.hits, self.misses, rate)
    }

    pub fn clear(&mut self) {
        self.tokens.clear();
        self.insertion_order.clear();
    }

    pub fn len(&self) -> usize {
        self.tokens.len()
    }

    pub fn is_empty(&self) -> bool {
        self.tokens.is_empty()
    }
}

/// Variable: Represents a defined variable in compilation
#[derive(Debug, Clone)]
pub struct Variable {
    pub name: String,
    pub var_type: String,
    pub scope: u32,
    pub value: Option<String>,
}

/// Function: Represents a defined function in compilation
#[derive(Debug, Clone)]
pub struct Function {
    pub name: String,
    pub params: Vec<(String, String)>, // (name, type)
    pub return_type: String,
    pub scope: u32,
}

/// SharedState: Thread-safe shared compilation state
/// All 4 workers can read/write to these shared structures (O(1) lookups via HashMap)
pub struct SharedState {
    pub token_cache: Arc<Mutex<TokenCache>>,
    pub variables: Arc<Mutex<HashMap<String, Variable>>>,
    pub functions: Arc<Mutex<HashMap<String, Function>>>,
    pub errors: Arc<Mutex<Vec<String>>>,
    total_tokens: AtomicU64,
    total_time_ns: AtomicU64,
}

impl SharedState {
    pub fn new(cache_capacity: usize) -> Self {
        SharedState {
            token_cache: Arc::new(Mutex::new(TokenCache::new(cache_capacity))),
            variables: Arc::new(Mutex::new(HashMap::new())),
            functions: Arc::new(Mutex::new(HashMap::new())),
            errors: Arc::new(Mutex::new(Vec::new())),
            total_tokens: AtomicU64::new(0),
            total_time_ns: AtomicU64::new(0),
        }
    }

    /// Add variable to shared state (O(1) HashMap insert)
    pub fn add_variable(&self, var: Variable) -> Result<(), String> {
        match self.variables.lock() {
            Ok(mut vars) => {
                vars.insert(var.name.clone(), var);
                Ok(())
            }
            Err(e) => Err(format!("Failed to lock variables: {}", e)),
        }
    }

    /// Lookup variable by name (O(1) HashMap get)
    pub fn lookup_variable(&self, name: &str) -> Option<Variable> {
        match self.variables.lock() {
            Ok(vars) => vars.get(name).cloned(),
            Err(_) => None,
        }
    }

    /// Add function to shared state (O(1) HashMap insert)
    pub fn add_function(&self, func: Function) -> Result<(), String> {
        match self.functions.lock() {
            Ok(mut funcs) => {
                funcs.insert(func.name.clone(), func);
                Ok(())
            }
            Err(e) => Err(format!("Failed to lock functions: {}", e)),
        }
    }

    /// Lookup function by name (O(1) HashMap get)
    pub fn lookup_function(&self, name: &str) -> Option<Function> {
        match self.functions.lock() {
            Ok(funcs) => funcs.get(name).cloned(),
            Err(_) => None,
        }
    }

    /// Record error
    pub fn record_error(&self, error: String) {
        if let Ok(mut errs) = self.errors.lock() {
            errs.push(error);
        }
    }

    /// Get all variables as Vec
    pub fn get_variables(&self) -> Vec<Variable> {
        match self.variables.lock() {
            Ok(vars) => vars.values().cloned().collect(),
            Err(_) => Vec::new(),
        }
    }

    /// Get all functions as Vec
    pub fn get_functions(&self) -> Vec<Function> {
        match self.functions.lock() {
            Ok(funcs) => funcs.values().cloned().collect(),
            Err(_) => Vec::new(),
        }
    }

    /// Get all errors
    pub fn get_errors(&self) -> Vec<String> {
        match self.errors.lock() {
            Ok(errs) => errs.clone(),
            Err(_) => Vec::new(),
        }
    }

    /// Update total metrics
    pub fn update_metrics(&self, tokens: u64, time_ns: u64) {
        self.total_tokens.fetch_add(tokens, Ordering::Relaxed);
        self.total_time_ns.fetch_add(time_ns, Ordering::Relaxed);
    }

    /// Get metrics
    pub fn get_metrics(&self) -> (u64, u64) {
        (
            self.total_tokens.load(Ordering::Relaxed),
            self.total_time_ns.load(Ordering::Relaxed),
        )
    }

    /// Get token cache hit rate
    pub fn token_cache_hit_rate(&self) -> f64 {
        match self.token_cache.lock() {
            Ok(cache) => cache.hit_rate(),
            Err(_) => 0.0,
        }
    }

    pub fn clear(&self) {
        if let Ok(mut cache) = self.token_cache.lock() {
            cache.clear();
        }
        if let Ok(mut vars) = self.variables.lock() {
            vars.clear();
        }
        if let Ok(mut funcs) = self.functions.lock() {
            funcs.clear();
        }
        if let Ok(mut errs) = self.errors.lock() {
            errs.clear();
        }
    }
}

