#[test]
fn test_cache_hit_rate_validation() {
    let mut cache = freelang_compiler::shared_memory::TokenCache::new(100);

    // Insert 50 tokens
    for i in 0..50 {
        let token = freelang_compiler::shared_memory::Token::new(
            i,
            0,
            format!("token_{}", i),
            1,
            i as u32,
        );
        cache.insert(token);
    }

    // Lookup with mix of hits and misses
    for i in 0..50 {
        let _ = cache.lookup(i);  // 50 hits
    }
    for i in 100..110 {
        let _ = cache.lookup(i);  // 10 misses
    }

    let hit_rate = cache.hit_rate();
    let (hits, misses, _) = cache.stats();

    println!("✓ Test 7: Cache hit rate - {} hits, {} misses, {:.1}% rate",
             hits, misses, hit_rate * 100.0);

    assert!(hit_rate > 0.8);  // Should be > 80% hit rate
}

