   148→    VarDecl {
   149→        name: String,
   150→        value: Expr,
   151→    },
   152→
   153→    // Variable Assignment: x = expr
   154→    Assign {
   155→        name: String,
   156→        value: Expr,
   157→    },
   158→
   159→    // For Loop: for i in range(0, 10) { ... }
   160→    ForLoop {
   161→        var: String,
   162→        start: i64,
   163→        end: i64,
   164→        body: Vec<Stmt>,
   165→    },
   166→
   167→    // If Statement: if cond { ... } else { ... }
   168→    If {
   169→        condition: Expr,
   170→        then_body: Vec<Stmt>,
   171→        else_body: Option<Vec<Stmt>>,
   172→    },
   173→
   174→    // Return Statement
   175→    Return(Option<Expr>),
   176→
   177→    // Expression Statement
   178→    Expr(Expr),
