     5→use std::collections::HashMap;
     6→use std::io::{self, Write};
     7→
     8→// ============================================================================
     9→// Lexer - 토큰화
    10→// ============================================================================
    11→
    12→#[derive(Debug, Clone, PartialEq)]
    13→enum Token {
    14→    // Keywords
    15→    Fn,
    16→    Pub,
    17→    Module,
    18→    Use,
    19→    Type,
    20→    Struct,
    21→    If,
    22→    Else,
    23→    For,
    24→    While,
    25→    Return,
    26→    Let,
    27→    Mut,
    28→    True,
    29→    False,
    30→
    31→    // Identifiers & Literals
    32→    Identifier(String),
    33→    Number(i64),
    34→    String(String),
    35→
    36→    // Operators
    37→    Plus,
    38→    Minus,
    39→    Star,
    40→    Slash,
    41→    Percent,
    42→    Equal,
    43→    EqualEqual,
    44→    NotEqual,
    45→    Less,
    46→    Greater,
    47→    LessEqual,
    48→    GreaterEqual,
    49→    And,
    50→    Or,
    51→    Not,
    52→    Xor,
    53→    Arrow,
    54→
    55→    // Delimiters
    56→    LeftParen,
    57→    RightParen,
    58→    LeftBrace,
    59→    RightBrace,
    60→    LeftBracket,
    61→    RightBracket,
    62→    Comma,
    63→    Dot,
    64→    Colon,
    65→    Semicolon,
    66→    Pipe,
    67→
    68→    // Special
    69→    Eof,
    70→}
    71→
    72→struct Lexer {
    73→    input: Vec<char>,
    74→    pos: usize,
    75→}
    76→
    77→impl Lexer {
    78→    fn new(input: &str) -> Self {
    79→        Lexer {
    80→            input: input.chars().collect(),
    81→            pos: 0,
    82→        }
    83→    }
    84→
    85→    fn current_char(&self) -> Option<char> {
    86→        if self.pos < self.input.len() {
    87→            Some(self.input[self.pos])
    88→        } else {
    89→            None
    90→        }
    91→    }
    92→
    93→    fn peek_char(&self) -> Option<char> {
    94→        if self.pos + 1 < self.input.len() {
    95→            Some(self.input[self.pos + 1])
    96→        } else {
    97→            None
    98→        }
    99→    }
   100→
   101→    fn advance(&mut self) {
   102→        self.pos += 1;
   103→    }
   104→
   105→    fn skip_whitespace(&mut self) {
   106→        while let Some(ch) = self.current_char() {
   107→            if ch.is_whitespace() {
   108→                self.advance();
   109→            } else {
   110→                break;
   111→            }
   112→        }
   113→    }
   114→
   115→    fn read_identifier(&mut self) -> String {
   116→        let mut result = String::new();
   117→        while let Some(ch) = self.current_char() {
   118→            if ch.is_alphanumeric() || ch == '_' {
   119→                result.push(ch);
   120→                self.advance();
   121→            } else {
   122→                break;
   123→            }
   124→        }
   125→        result
   126→    }
   127→
   128→    fn read_number(&mut self) -> i64 {
   129→        let mut result = 0i64;
   130→        while let Some(ch) = self.current_char() {
   131→            if ch.is_digit(10) {
   132→                result = result * 10 + (ch as i64 - '0' as i64);
   133→                self.advance();
   134→            } else {
   135→                break;
   136→            }
   137→        }
   138→        result
   139→    }
   140→
   141→    fn next_token(&mut self) -> Token {
   142→        self.skip_whitespace();
   143→
   144→        match self.current_char() {
   145→            None => Token::Eof,
   146→            Some(ch) => {
   147→                match ch {
   148→                    '(' => {
   149→                        self.advance();
   150→                        Token::LeftParen
   151→                    }
   152→                    ')' => {
   153→                        self.advance();
   154→                        Token::RightParen
   155→                    }
   156→                    '{' => {
   157→                        self.advance();
   158→                        Token::LeftBrace
   159→                    }
   160→                    '}' => {
   161→                        self.advance();
   162→                        Token::RightBrace
   163→                    }
   164→                    '[' => {
   165→                        self.advance();
   166→                        Token::LeftBracket
   167→                    }
   168→                    ']' => {
   169→                        self.advance();
   170→                        Token::RightBracket
   171→                    }
   172→                    ',' => {
   173→                        self.advance();
   174→                        Token::Comma
   175→                    }
   176→                    '.' => {
   177→                        self.advance();
   178→                        Token::Dot
   179→                    }
   180→                    ':' => {
   181→                        self.advance();
   182→                        Token::Colon
   183→                    }
   184→                    ';' => {
   185→                        self.advance();
   186→                        Token::Semicolon
   187→                    }
   188→                    '|' => {
   189→                        self.advance();
   190→                        Token::Pipe
   191→                    }
   192→                    '+' => {
   193→                        self.advance();
   194→                        Token::Plus
   195→                    }
   196→                    '-' => {
   197→                        self.advance();
   198→                        if self.current_char() == Some('>') {
   199→                            self.advance();
   200→                            Token::Arrow
   201→                        } else {
   202→                            Token::Minus
   203→                        }
   204→                    }
   205→                    '*' => {
   206→                        self.advance();
   207→                        Token::Star
   208→                    }
   209→                    '/' => {
   210→                        self.advance();
   211→                        Token::Slash
   212→                    }
   213→                    '%' => {
   214→                        self.advance();
   215→                        Token::Percent
   216→                    }
   217→                    '=' => {
   218→                        self.advance();
   219→                        if self.current_char() == Some('=') {
   220→                            self.advance();
   221→                            Token::EqualEqual
   222→                        } else {
   223→                            Token::Equal
   224→                        }
   225→                    }
   226→                    '!' => {
   227→                        self.advance();
   228→                        if self.current_char() == Some('=') {
   229→                            self.advance();
   230→                            Token::NotEqual
   231→                        } else {
   232→                            Token::Not
   233→                        }
   234→                    }
   235→                    '<' => {
   236→                        self.advance();
   237→                        if self.current_char() == Some('=') {
   238→                            self.advance();
   239→                            Token::LessEqual
   240→                        } else {
   241→                            Token::Less
   242→                        }
   243→                    }
   244→                    '>' => {
   245→                        self.advance();
   246→                        if self.current_char() == Some('=') {
   247→                            self.advance();
   248→                            Token::GreaterEqual
   249→                        } else {
   250→                            Token::Greater
   251→                        }
   252→                    }
   253→                    '&' => {
   254→                        self.advance();
   255→                        Token::And
   256→                    }
   257→                    '^' => {
   258→                        self.advance();
   259→                        Token::Xor
   260→                    }
   261→                    '"' => {
   262→                        self.advance();
   263→                        let mut s = String::new();
   264→                        while let Some(c) = self.current_char() {
   265→                            if c == '"' {
   266→                                self.advance();
   267→                                break;
   268→                            }
   269→                            s.push(c);
   270→                            self.advance();
   271→                        }
   272→                        Token::String(s)
   273→                    }
   274→                    _ => {
   275→                        if ch.is_digit(10) {
   276→                            Token::Number(self.read_number())
   277→                        } else if ch.is_alphabetic() || ch == '_' {
   278→                            let ident = self.read_identifier();
   279→                            match ident.as_str() {
   280→                                "fn" => Token::Fn,
   281→                                "pub" => Token::Pub,
   282→                                "module" => Token::Module,
   283→                                "use" => Token::Use,
   284→                                "type" => Token::Type,
   285→                                "struct" => Token::Struct,
   286→                                "if" => Token::If,
   287→                                "else" => Token::Else,
   288→                                "for" => Token::For,
   289→                                "while" => Token::While,
   290→                                "return" => Token::Return,
   291→                                "let" => Token::Let,
   292→                                "mut" => Token::Mut,
   293→                                "true" => Token::True,
   294→                                "false" => Token::False,
   295→                                _ => Token::Identifier(ident),
   296→                            }
   297→                        } else {
   298→                            self.advance();
   299→                            self.next_token()
   300→                        }
   301→                    }
   302→                }
   303→            }
   304→        }
   305→    }
   306→}
