#[derive(Clone, Debug)]
pub enum Expr {
    // Literals
    Literal(Value),

    // Variables
    Variable(String),

    // Binary Operations
    BinOp {
        left: Box<Expr>,
        op: String,
        right: Box<Expr>,
    },

    // Field Access: x.field
    FieldAccess {
        object: Box<Expr>,
        field: String,
    },

    // Function Call: fn_name(arg1, arg2)
    FunctionCall {
        name: String,
        args: Vec<Expr>,
    },

    // Array Append: arr + [item]
    ArrayAppend {
        array: Box<Expr>,
        item: Box<Expr>,
    },

    // Struct Constructor
    StructConstruct {
        name: String,
        fields: HashMap<String, Expr>,
    },
}

