    },

    // Variable Assignment: x = expr
    Assign {
        name: String,
        value: Expr,
    },

    // For Loop: for i in range(0, 10) { ... }
    ForLoop {
        var: String,
        start: i64,
        end: i64,
        body: Vec<Stmt>,
    },

    // If Statement: if cond { ... } else { ... }
    If {
        condition: Expr,
        then_body: Vec<Stmt>,
        else_body: Option<Vec<Stmt>>,
    },

    // Return Statement
    Return(Option<Expr>),

    // Expression Statement
    Expr(Expr),
}

