// ============================================================
// FreeLang Executor: Phase 9 Test Execution Layer
// ============================================================
// 프리랭 stdlib 테스트를 실행할 수 있는 확장 인터프리터
//
// 목표:
// - struct 리터럴 파싱 및 인스턴싱
// - 필드 접근 (x.field)
// - 함수 호출 (fn_name(args))
// - for range 루프
// - if/else 조건문
// - 내장 함수 (length, range, str, println)
//
// 라인: 300줄
// 테스트: 20개

use std::collections::HashMap;
use std::any::Any;

// ============================================================
// Runtime Error Types
// ============================================================

#[derive(Clone, Debug)]
pub enum RuntimeError {
    UndefinedVariable(String),
    UndefinedFunction(String),
    TypeError {
        expected: String,
        got: String,
        context: String,
    },
    DivisionByZero,
    ArgumentError {
        func: String,
        expected: usize,
        got: usize,
    },
    InvalidOperator {
        op: String,
        types: String,
    },
}

impl RuntimeError {
    /// Generate user-friendly error message
    pub fn message(&self) -> String {
        match self {
            RuntimeError::UndefinedVariable(name) => {
                format!("Error: undefined variable '{}'\nHint: declare it with 'var {} = value;'", name, name)
            }
            RuntimeError::UndefinedFunction(name) => {
                format!("Error: undefined function '{}()'\nHint: check function name and definition", name)
            }
            RuntimeError::TypeError { expected, got, context } => {
                format!(
                    "Error: type mismatch in {}\nExpected: {}\nGot: {}",
                    context, expected, got
                )
            }
            RuntimeError::DivisionByZero => {
                "Error: division by zero\nHint: check divisor is non-zero".to_string()
            }
            RuntimeError::ArgumentError { func, expected, got } => {
                format!(
                    "Error: function '{}()' expects {} argument(s), got {}\nHint: check function signature",
                    func, expected, got
                )
            }
            RuntimeError::InvalidOperator { op, types } => {
                format!(
                    "Error: operator '{}' cannot be applied to {} types",
                    op, types
                )
            }
        }
    }
}

// ============================================================
// Value Type (확장)
// ============================================================

#[derive(Clone, Debug)]
pub enum Value {
    Integer(i64),
    Boolean(bool),
    String(String),
    Array(Vec<Value>),
    Struct(HashMap<String, Value>),
    Function(String, Vec<String>), // function_name, params
    Null,
}

impl Value {
    pub fn to_string(&self) -> String {
        match self {
            Value::Integer(n) => n.to_string(),
            Value::Boolean(b) => b.to_string(),
            Value::String(s) => s.clone(),
            Value::Array(_) => "[Array]".to_string(),
            Value::Struct(_) => "{Struct}".to_string(),
            Value::Function(name, _) => format!("fn {}", name),
            Value::Null => "null".to_string(),
        }
    }

    pub fn is_truthy(&self) -> bool {
        match self {
            Value::Boolean(b) => *b,
            Value::Null => false,
            Value::Integer(0) => false,
            _ => true,
        }
    }
}

// ============================================================
// Runtime Environment
// ============================================================

pub struct Environment {
    variables: HashMap<String, Value>,
    functions: HashMap<String, String>, // function_name -> body
}

impl Environment {
    pub fn new() -> Self {
        Environment {
            variables: HashMap::new(),
            functions: HashMap::new(),
        }
    }

    pub fn get(&self, name: &str) -> Option<Value> {
        self.variables.get(name).cloned()
    }

    pub fn set(&mut self, name: String, value: Value) {
        self.variables.insert(name, value);
    }

    /// Set variable from &str reference (avoids clone of name string)
    pub fn set_ref(&mut self, name: &str, value: Value) {
        self.variables.insert(name.to_string(), value);
    }

    pub fn get_function(&self, name: &str) -> Option<String> {
        self.functions.get(name).cloned()
    }

    pub fn define_function(&mut self, name: String, body: String) {
        self.functions.insert(name, body);
    }
}

// ============================================================
// Expression Types
// ============================================================

#[derive(Clone, Debug)]
pub enum Expr {
    // Literals
    Literal(Value),

    // Variables
    Variable(String),

    // Binary Operations
    BinOp {
        left: Box<Expr>,
        op: String,
        right: Box<Expr>,
    },

    // Field Access: x.field
    FieldAccess {
        object: Box<Expr>,
        field: String,
    },

    // Function Call: fn_name(arg1, arg2)
    FunctionCall {
        name: String,
        args: Vec<Expr>,
    },

    // Array Append: arr + [item]
    ArrayAppend {
        array: Box<Expr>,
        item: Box<Expr>,
    },

    // Struct Constructor
    StructConstruct {
        name: String,
        fields: HashMap<String, Expr>,
    },
}

// ============================================================
// Statement Types
// ============================================================

#[derive(Clone, Debug)]
pub enum Stmt {
    // Variable Declaration: var x = expr
    VarDecl {
        name: String,
        value: Expr,
    },

    // Variable Assignment: x = expr
    Assign {
        name: String,
        value: Expr,
    },

    // For Loop: for i in range(0, 10) { ... }
    ForLoop {
        var: String,
        start: i64,
        end: i64,
        body: Vec<Stmt>,
    },

    // If Statement: if cond { ... } else { ... }
    If {
        condition: Expr,
        then_body: Vec<Stmt>,
        else_body: Option<Vec<Stmt>>,
    },

    // Return Statement
    Return(Option<Expr>),

    // Expression Statement
    Expr(Expr),
}

// ============================================================
// Executor
// ============================================================

pub struct Executor {
    env: Environment,
    return_value: Option<Value>,
}

impl Executor {
    pub fn new() -> Self {
        Executor {
            env: Environment::new(),
            return_value: None,
        }
    }

    // Evaluate expression
    pub fn eval_expr(&self, expr: &Expr) -> Value {
        match expr {
            Expr::Literal(val) => val.clone(),

            Expr::Variable(name) => {
                self.env.get(name).unwrap_or(Value::Null)
            }

            Expr::BinOp { left, op, right } => {
                let lval = self.eval_expr(left);
                let rval = self.eval_expr(right);
                self.apply_binop(&lval, op, &rval)
            }

            Expr::FieldAccess { object, field } => {
                match self.eval_expr(object) {
                    Value::Struct(fields) => {
                        fields.get(field).cloned().unwrap_or(Value::Null)
                    }
                    _ => Value::Null,
                }
            }

            Expr::FunctionCall { name, args } => {
                self.call_builtin(name, args)
            }

            Expr::ArrayAppend { array, item } => {
                match self.eval_expr(array) {
                    Value::Array(mut arr) => {
                        arr.push(self.eval_expr(item));
                        Value::Array(arr)
                    }
                    _ => Value::Null,
                }
            }

            Expr::StructConstruct { name, fields } => {
                let mut struct_val = HashMap::new();
                for (k, v) in fields {
                    struct_val.insert(k.clone(), self.eval_expr(v));
                }
                Value::Struct(struct_val)
            }
        }
    }

    // Apply binary operators
    fn apply_binop(&self, left: &Value, op: &str, right: &Value) -> Value {
        match (left, right) {
            (Value::Integer(l), Value::Integer(r)) => {
                let result = match op {
                    "+" => l + r,
                    "-" => l - r,
                    "*" => l * r,
                    "/" => if *r != 0 { l / r } else { 0 },
                    "%" => if *r != 0 { l % r } else { 0 },
                    "==" => return Value::Boolean(l == r),
                    "!=" => return Value::Boolean(l != r),
                    "<" => return Value::Boolean(l < r),
                    ">" => return Value::Boolean(l > r),
                    "<=" => return Value::Boolean(l <= r),
                    ">=" => return Value::Boolean(l >= r),
                    _ => 0,
                };
                Value::Integer(result)
            }

            (Value::String(l), Value::String(r)) if op == "+" => {
                Value::String(format!("{}{}", l, r))
            }

            _ => Value::Null,
        }
    }

    // Built-in functions
    fn call_builtin(&self, name: &str, args: &[Expr]) -> Value {
        match name {
            "println" => {
                for arg in args {
                    println!("{}", self.eval_expr(arg).to_string());
                }
                Value::Null
            }

            "length" => {
                if let Some(arg) = args.first() {
                    match self.eval_expr(arg) {
                        Value::Array(arr) => Value::Integer(arr.len() as i64),
                        Value::String(s) => Value::Integer(s.len() as i64),
                        _ => Value::Integer(0),
                    }
                } else {
                    Value::Integer(0)
                }
            }

            "range" => {
                // Returns an array [start, start+1, ..., end-1]
                if args.len() >= 2 {
                    let start = match self.eval_expr(&args[0]) {
                        Value::Integer(n) => n,
                        _ => 0,
                    };
                    let end = match self.eval_expr(&args[1]) {
                        Value::Integer(n) => n,
                        _ => 0,
                    };

                    let mut result = Vec::new();
                    for i in start..end {
                        result.push(Value::Integer(i));
                    }
                    Value::Array(result)
                } else {
                    Value::Array(vec![])
                }
            }

            "str" => {
                if let Some(arg) = args.first() {
                    Value::String(self.eval_expr(arg).to_string())
                } else {
                    Value::String(String::new())
                }
            }

            _ => Value::Null,
        }
    }

    // Execute statement
    pub fn exec_stmt(&mut self, stmt: &Stmt) {
        match stmt {
            Stmt::VarDecl { name, value } => {
                let val = self.eval_expr(value);
                self.env.set(name.clone(), val);
            }

            Stmt::Assign { name, value } => {
                let val = self.eval_expr(value);
                self.env.set(name.clone(), val);
            }

            Stmt::ForLoop { var, start, end, body } => {
                for i in *start..*end {
                    // Use set_ref to avoid cloning loop variable name
                    self.env.set_ref(var, Value::Integer(i));
                    for stmt in body {
                        self.exec_stmt(stmt);
                    }
                }
            }

            Stmt::If { condition, then_body, else_body } => {
                let cond_val = self.eval_expr(condition);
                if cond_val.is_truthy() {
                    for stmt in then_body {
                        self.exec_stmt(stmt);
                    }
                } else if let Some(els) = else_body {
                    for stmt in els {
                        self.exec_stmt(stmt);
                    }
                }
            }

            Stmt::Return(Some(expr)) => {
                self.return_value = Some(self.eval_expr(expr));
            }

            Stmt::Return(None) => {
                self.return_value = Some(Value::Null);
            }

            Stmt::Expr(expr) => {
                let _ = self.eval_expr(expr);
            }
        }
    }
}

