fn test_invalid_operator_numbers() {
    let mut executor = Executor::new();

    // Use an invalid operator like '&' on integers
    let expr = Expr::BinOp {
        left: Box::new(Expr::Literal(Value::Integer(5))),
        op: "&".to_string(),
        right: Box::new(Expr::Literal(Value::Integer(3))),
    };

    let result = executor.eval_expr(&expr);

    // Should return null and record error
    assert_eq!(result, Value::Null);
    assert!(executor.has_errors());

    println!("✓ Test 19: Invalid operator for numbers detected");
}

