#[test]
fn test_nested_error_context() {
    let mut executor = Executor::new();

    // Nested expression: str(undefined_var)
    let expr = Expr::FunctionCall {
        name: "str".to_string(),
        args: vec![Expr::Variable("undefined".to_string())],
    };

    executor.eval_expr(&expr);

    // Should record error for undefined variable
    // (called within str function context)
    assert!(executor.has_errors());

    println!("✓ Test 20: Nested error context tracked");
